let IDIOMA = "pt";

function detectarIdioma() {
  try {
    const salvo = localStorage.getItem("painel.idioma");
    if (salvo && TXT[salvo]) return salvo;
  } catch { /* sem armazenamento */ }
  const nav = (navigator.language || "en").slice(0, 2).toLowerCase();
  return TXT[nav] ? nav : "en";
}

function t(chave, vars) {
  let s = TXT[IDIOMA]?.[chave] ?? TXT.en[chave] ?? chave;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined ? vars[k] : m));
  return s;
}

// aplica as traduções nos elementos com data-i18n / data-i18n-title / data-i18n-aria
function traduzirPagina() {
  document.documentElement.lang = LOCALES[IDIOMA];
  document.title = t("app");
  document.querySelectorAll("[data-i18n]").forEach((el) => (el.textContent = t(el.dataset.i18n)));
  document.querySelectorAll("[data-i18n-title]").forEach((el) => (el.title = t(el.dataset.i18nTitle)));
  document.querySelectorAll("[data-i18n-aria]").forEach((el) => el.setAttribute("aria-label", t(el.dataset.i18nAria)));
}

